#include <cstdlib>
#include <iostream>
#include <new>
#include <vector>

static std::size_t g_allocations{0};

void* operator new(std::size_t size)
{
    ++g_allocations;
    if (void* p{std::malloc(size)}) return p;
    throw std::bad_alloc{};
}

void operator delete(void* p) noexcept
{
    std::free(p);
}

int main()
{
    std::vector<int> v(10);
    std::cout << g_allocations << " allocations\n";
}
